pm.test(`Employee is added (${scenario})`, function () {
    pm.response.to.have.status(201);
});

pm.test("Response matches the employee schema", function () {
    const raw = pm.collectionVariables.get("employeePostSchema");
    pm.expect(raw, "employeePostSchema fixture is missing").to.be.a("string").and.not.empty;
    pm.response.to.have.jsonSchema(JSON.parse(raw));
});

pm.test("Response says the employee is saved", function () {
    pm.expect(norm((response.messages || {}).success), "messages.success").to.eql(cell("emp_successMessage"));
});

pm.test(`Employee details match what was sent (${scenario})`, function () {
    ["firstName", "middleName", "lastName", "locationId"].forEach(field => {
        pm.expect(norm(responseData[field]), field).to.eql(expected[field]);
    });
    pm.expect(norm(responseData.joined_date), "joined_date").to.eql(expected.joinedDate);
    pm.expect(norm((responseData.Location || {}).id), "Location.id").to.eql(expected.locationId);
});

pm.test("New employee is active and added today", function () {
    pm.expect(responseData.termination_id, "termination_id").to.be.null;
    // the server date can be a day off the UTC date of the test runner
    const days = Math.abs(new Date(norm(responseData.added_date)) - new Date(new Date().toISOString().split("T")[0])) / 86400000;
    pm.expect(days, `added_date ${norm(responseData.added_date)}`).to.be.at.most(1);
});

// employeeId cell of the expected result: {SENT} = the id sent, {GENERATED} = a system id (not blank), blank = null
const expectedId = cell("emp_expectedEmployeeId");
pm.test(`Employee ID is ${expectedId === "{GENERATED}" ? "generated by the system" : "as expected"} (${scenario})`, function () {
    if (expectedId === "{GENERATED}") {
        pm.expect(norm(responseData.employeeId), "employeeId").to.match(/^\S+$/);
    } else if (expectedId === "{SENT}") {
        pm.expect(norm(responseData.employeeId), "employeeId").to.eql(expected.employeeId);
    } else {
        pm.expect(responseData.employeeId, "employeeId").to.be.null;
    }
});

