// the fixtures serve every row of the CSV: they are created in the first iteration only
if (pm.info.iteration > 0) {
    pm.execution.skipRequest();
} else {
    // a failed precondition must not resend the previous body: this placeholder is rejected as malformed JSON
    pm.variables.set("requestBody", "request body was not built");
    const fixtures = JSON.parse(pm.environment.get("sysuserlist_fixtures") || "{}");
    // userOne = "<employee letter>|<role keys, comma separated>|<status 1 or 0>"
    const spec = cell("userOne").split("|");
    if (spec.length !== 3 || !["A", "B"].includes(spec[0]) || spec[1] === "" || !["0", "1"].includes(spec[2])) {
        throw new Error("Test data error: userOne must be <A|B>|<roles>|<0|1>");
    }
    const owner = fixtures[spec[0]];
    if (!owner || !owner.empNumber) {
        throw new Error(`Precondition failed: employee ${spec[0]} not created by ADMIN-547/ADMIN-548`);
    }
    const buildBody = current => {
        const roleIds = {};
        spec[1].split(",").forEach(roleKey => {
            if (!current.roles[roleKey]) {
                throw new Error(`Test data error: role key ${roleKey} in userOne is unknown`);
            }
            const field = roleKey.startsWith("ess") ? "essrole" : (roleKey.startsWith("sup") ? "supervisorrole" : "adminrole");
            roleIds[field] = current.roles[roleKey];
        });
        // random password for a user nobody logs in with
        const password = `Sul!${Math.random().toString(36).slice(2, 10)}${Date.now().toString(36)}9A`;
        const user = {
            user_name: `${current.tag}.one`,
            ...roleIds,
            emp_number: owner.empNumber,
            password: password, confirmpassword: password,
            status: Number(spec[2])
        };
        pm.variables.set("fixtureUser", JSON.stringify({
            key: "one", user_name: user.user_name, employee: spec[0], status: spec[2],
            roles: spec[1].split(",").map(roleKey => current.roles[roleKey])
        }));
        pm.variables.set("requestBody", JSON.stringify(user));
    };
    // role ids come from /api/userRoles: ESS and Supervisor, plus another assignable role of each type
    // and an assignable admin-type role that is not the full Admin role (the essrole/supervisorrole/adminrole filters)
    api("GET", "/api/userRoles", undefined, function (err, res) {
        let roles = [];
        try {
            roles = (res.json() || {}).data || [];
        } catch (e) {
            roles = [];
        }
        const pick = (typeId, name) => roles.find(r => norm(r.typeId) === typeId && norm(r.name) === name);
        const found = {
            ess: pick("2", "ESS"),
            essAlt: roles.find(r => norm(r.typeId) === "2" && r.is_assignable === true && norm(r.name) !== "ESS"),
            sup: pick("3", "Supervisor"),
            supAlt: roles.find(r => norm(r.typeId) === "3" && r.is_assignable === true && norm(r.name) !== "Supervisor"),
            admin: roles.find(r => norm(r.typeId) === "1" && r.is_assignable === true && norm(r.name) !== "Admin")
        };
        const missing = Object.keys(found).filter(k => !found[k]);
        if (err || missing.length > 0) {
            throw new Error(`Precondition failed: user roles ${missing.join(", ")} not found in /api/userRoles`);
        }
        const current = JSON.parse(pm.environment.get("sysuserlist_fixtures") || "{}");
        current.roles = {};
        Object.keys(found).forEach(k => { current.roles[k] = norm(found[k].id); });
        pm.environment.set("sysuserlist_fixtures", JSON.stringify(current));
        buildBody(current);
    });
}

