// sul_query holds key=value pairs separated by "&". Tokens: {TAG} = the user-name tag of the run,
// {USER.<key>} = user name of a fixture user, {A.<field>} / {B.<field>} = a field of a fixture employee,
// {ROLE.<key>} = a role id looked up by ADMIN-549; "|upper" upper-cases the value
const lookup = (scope, field) => {
    if (scope === "USER") {
        return norm((fixtures.users[field] || {}).user_name);
    }
    const source = scope === "ROLE" ? fixtures.roles : fixtures[scope];
    if (!source || source[field] === undefined) {
        throw new Error(`Test data error: token ${scope}.${field} is unknown`);
    }
    return norm(source[field]);
};
const resolve = text => text.replace(/\{(TAG|(A|B|ROLE|USER)\.(\w+))(\|upper)?\}/g, (match, token, scope, field, upper) => {
    const value = token === "TAG" ? fixtures.tag : lookup(scope, field);
    if (value === "") {
        throw new Error(`Test data error: token ${token} resolves to an empty value`);
    }
    return upper ? value.toUpperCase() : value;
});
const query = cell("sul_query");
if (query !== "") {
    query.split("&").forEach(pair => {
        const at = pair.indexOf("=");
        if (at < 1) {
            throw new Error(`Test data error: "${pair}" in sul_query is not key=value`);
        }
        pm.request.url.addQueryParams([{ key: pair.slice(0, at), value: resolve(pair.slice(at + 1)) }]);
    });
}
if (!["list", "availability"].includes(cell("sul_mode"))) {
