const scenario = `${cell("scenario")}${defect}`;
const users = fixtures.users || {};
const keyOf = {};
Object.keys(users).forEach(key => { keyOf[norm(users[key].id)] = key; });

// sul_expected: fixture user keys; "|" separates positions, "+" joins users whose order is not defined (ties);
// "*" = do not check which users are returned
const expectedText = cell("sul_expected");
const groups = expectedText === "" || expectedText === "*" ? [] : expectedText.split("|").map(g => g.split("+"));
const expectedKeys = [].concat(...groups);

if (cell("sul_mode") === "availability") {
    pm.test(`User name availability is returned (${scenario})`, function () {
        pm.response.to.have.status(200);
    });

    pm.test(`Response matches the user name availability schema (${scenario})`, function () {
        const raw = pm.collectionVariables.get("systemUserAvailabilitySchema");
        pm.expect(raw, "systemUserAvailabilitySchema fixture is missing").to.be.a("string").and.not.empty;
        pm.response.to.have.jsonSchema(JSON.parse(raw));
    });

    pm.test(`Only taken user names are reported (${scenario})`, function () {
        pm.expect(response.data, "data").to.eql(expectedKeys.map(key => users[key].user_name));
    });
} else {
    const rows = Array.isArray(response.data) ? response.data : [];
    const meta = response.meta || {};
    // rows are named by fixture key; any other user shows up as "other <id>"
    const actual = rows.map(row => keyOf[norm(row.id)] || `other ${norm(row.id)}`);

    pm.test(`System user list is returned (${scenario})`, function () {
        pm.response.to.have.status(200);
    });

    pm.test(`Response matches the system user list schema (${scenario})`, function () {
        const raw = pm.collectionVariables.get("systemUserListSchema");
        pm.expect(raw, "systemUserListSchema fixture is missing").to.be.a("string").and.not.empty;
        pm.response.to.have.jsonSchema(JSON.parse(raw));
    });

    if (expectedText !== "*") {
        pm.test(`Only the users matching the parameters are returned (${scenario})`, function () {
            pm.expect([...actual].sort(), "users returned").to.eql([...expectedKeys].sort());
        });

        const total = cell("sul_total") === "" ? expectedKeys.length : Number(cell("sul_total"));
        pm.test(`meta.total is the number of matching users (${scenario})`, function () {
            pm.expect(meta.total, "meta.total").to.eql(total);
        });
    }

    if (cell("sul_ordered") === "true") {
        pm.test(`Users are returned in the requested order (${scenario})`, function () {
            let at = 0;
            groups.forEach(group => {
                const slice = actual.slice(at, at + group.length);
                pm.expect([...slice].sort(), `users at positions ${at + 1}-${at + group.length}`).to.eql([...group].sort());
                at += group.length;
            });
        });
    }

    if (cell("sul_maxRows") !== "") {
        pm.test(`At most ${cell("sul_maxRows")} users are returned without page[limit] (${scenario})`, function () {
            pm.expect(rows.length, "number of users returned").to.be.at.most(Number(cell("sul_maxRows")));
            pm.expect(meta.total, "meta.total").to.be.at.least(rows.length);
        });
    }

    // read-after-write: each listed fixture user carries the values it was created with
    const own = rows.filter(row => keyOf[norm(row.id)]);
    if (own.length > 0) {
        pm.test(`Listed users match the values they were saved with (${scenario})`, function () {
            own.forEach(row => {
                const user = users[keyOf[norm(row.id)]];
                pm.expect(norm(row.user_name), `${user.key} user_name`).to.eql(user.user_name);
                pm.expect(norm(row.emp_number), `${user.key} emp_number`).to.eql(fixtures[user.employee].empNumber);
                pm.expect(norm(row.status), `${user.key} status`).to.eql(user.status);
                pm.expect(norm(row.deleted), `${user.key} deleted`).to.eql(user.deleted ? "1" : "0");
            });
        });

        // sul_include: blocks expected on every row ("Employee|UserUserRole|UserRole|Regions"); others must be absent
        const blocks = cell("sul_include") === "" ? [] : cell("sul_include").split("|");
        pm.test(`Only the requested related data is included (${scenario})`, function () {
            own.forEach(row => {
                const key = keyOf[norm(row.id)];
                pm.expect(row.Employee !== undefined, `${key} Employee present`).to.eql(blocks.includes("Employee"));
                pm.expect(row.UserUserRole !== undefined, `${key} UserUserRole present`)
                    .to.eql(blocks.includes("UserUserRole") || blocks.includes("UserRole"));
                pm.expect(row.regions !== undefined, `${key} regions present`).to.eql(blocks.includes("Regions"));
                (row.UserUserRole || []).forEach((item, i) => {
                    pm.expect(item.UserRole !== undefined, `${key} UserUserRole[${i}].UserRole present`).to.eql(blocks.includes("UserRole"));
                });
            });
        });

        if (blocks.length > 0) {
            pm.test(`Included related data belongs to the user (${scenario})`, function () {
                own.forEach(row => {
                    const user = users[keyOf[norm(row.id)]];
                    const employee = fixtures[user.employee];
                    if (blocks.includes("Employee")) {
                        const e = row.Employee || {};
                        pm.expect(norm(e.empNumber), `${user.key} Employee.empNumber`).to.eql(employee.empNumber);
                        pm.expect(norm(e.employeeId), `${user.key} Employee.employeeId`).to.eql(employee.employeeId);
