                        pm.expect(e.termination_id, `${user.key} Employee.termination_id`).to.eql(employee.terminationId);
                    }
                    if (blocks.includes("UserUserRole") || blocks.includes("UserRole")) {
                        const items = row.UserUserRole || [];
                        pm.expect(items.length, `${user.key} number of UserUserRole items`).to.eql(user.roles.length);
                        items.forEach((item, i) => {
