     "appliedDate": cell("cand_appliedDate")
})



pm.variables.set("requestBody", requestBody);

const norm = v => (v === null || v === undefined) ? "" : String(v);
const cell = key => norm(pm.iterationData.get(key));
let response = {};
try {
    response = pm.response.json() || {};
} catch (e) {
    // not JSON: the checks below report it
}
const responseData = response || {};
const scenario = cell("scenario");

pm.test (`Validate the response code for (${scenario})`, function () {
    pm.response.to.have.status(Number(pm.iterationData.get("expectedStatus")));
})

pm.test (`Validate the response title for (${scenario})`, function () {
    pm.expect(responseData.error).to.eql(cell("expectedError"));
})

pm.test (`Validate the response details for (${scenario})`, function () {
    pm.expect(responseData.error_description).to.includes(cell("expectedErrorDescription"));
})

// teardown: find candidates this request created (keywords = this run's marker) and delete them
let sentBody = null;
try {
    sentBody = JSON.parse(pm.variables.get("requestBody"));
} catch (e) {
    // body is not JSON: nothing can be created
}
const marker = pm.variables.get("candidate_marker");
// rows without the marker (e.g. {} or []) are never matched, so other users' candidates are never deleted
if (sentBody && !Array.isArray(sentBody) && marker && sentBody.keywords === marker) {
    const candidatesUrl = `${pm.environment.get("baseURL")}/api/recruitment/candidates`;
    const authHeader = { "Authorization": `Bearer ${pm.environment.get("accessToken")}` };
    const listRequest = { url: `${candidatesUrl}?filter[keywords]=${marker}&page[limit]=50`, method: "GET", header: authHeader };
    const createdIds = res => {
        let data = null;
        try {
            data = (res.json() || {}).data;
        } catch (e) {
            // not JSON: reported by the checks below
        }
        return Array.isArray(data) ? data.filter(r => norm(r.keywords) === marker).map(r => String(r.id)) : null;
    };
    pm.sendRequest(listRequest, (err, res) => {
        const created = err ? null : createdIds(res);
        pm.test(`No candidate is created (${scenario})`, function () {
            pm.expect(err, "list request error").to.be.null;
            pm.expect(res.code, "list status").to.eql(200);
            pm.expect(created, "ids of candidates created by an invalid request").to.eql([]);
        });
        if (created && created.length > 0) {
            pm.sendRequest({
                url: candidatesUrl,
                method: "DELETE",
                header: Object.assign({ "Content-Type": "application/json" }, authHeader),
                body: { mode: "raw", raw: JSON.stringify({ ids: created.map(Number) }) }
            }, () => {
                pm.sendRequest(listRequest, (err2, res2) => {
                    pm.test("Candidates created by the rejected request are cleaned up", function () {
                        pm.expect(err2, "list request error").to.be.null;
                        pm.expect(createdIds(res2), "candidate ids still listed").to.eql([]);
                    });
                });
            });
        }
    });
}

const norm = v => (v === null || v === undefined) ? "" : String(v);

if (pm.info.iteration !== pm.info.iterationCount - 1) {
    pm.execution.skipRequest();
    return;
}

// vacancy created by RECRUITMENT-057 (fixture) plus any ids collected in vacancyIDs
const fixture = JSON.parse(pm.environment.get("vacancy_fixture_for_candi") || "{}");
const collected = JSON.parse(pm.environment.get("vacancyIDs") || "[]");
const ids = [...new Set([fixture.vacancyId, ...collected].map(norm).filter(id => id !== ""))].map(Number);

if (ids.length === 0) {
    throw new Error("Precondition failed: vacancy_fixture_for_candi / vacancyIDs not set by RECRUITMENT-057");
}

pm.variables.set("vacancyIdsToDelete", JSON.stringify(ids));
pm.variables.set("requestBody", JSON.stringify({ ids }));

const norm = v => (v === null || v === undefined) ? "" : String(v);
const vacancyIds = JSON.parse(pm.variables.get("vacancyIdsToDelete") || "[]").map(norm);

pm.test("Validate the response status code is 204", () => {
    pm.response.to.have.status(204);
});

